from . import curved_quad_pattern_nodes as response
from . import curved_quad_patch_nodes as four
from . import curved_quad_prolong_nodes as transfer
from . import curved_quad_quality_nodes as quality
from .path_surface_nodes import _Nodes
from . import boundary_quad_bridge_nodes as bridge

c = response.c
CONTEXT = ('Sources', 'Mapping', 'Approaches', 'Corners', 'Mouths', 'Depths', 'Plan')


def build(*, continuations=False, graded_transfer=False, repair_coarse=False, interpolation=False):
    name = 'Prochitecture Streets / Semantic cyclic pattern fit v4 / Direct affine map'
    if continuations: name += ' / Curb continuations'
    if graded_transfer: name += ' / Boundary graded transfer v1'
    if repair_coarse: name += ' / Bounded coarse correction v1'
    if graded_transfer and repair_coarse: name += ' / Consistent graded transfer v1'
    if interpolation: name += ' / Exact or smooth source charts v1'
    if name in bpy.data.node_groups: return bpy.data.node_groups[name]
    g = c.Graph(name)
    for key in ('Geometry', 'Pattern', 'Coefficients', *CONTEXT): g.socket(key, 'NodeSocketGeometry')
    for key in ('Radial Count', 'Pattern Rows', 'Pattern Radial', 'Pattern Sides'):
        g.socket(key, 'NodeSocketInt')
    g.socket('Input Valid', 'NodeSocketBool')
    for key in ('Geometry', 'Inspection Geometry', 'Constrained Pattern', 'Fitted Pattern', 'Status'):
        g.socket(key, 'NodeSocketGeometry', 'OUTPUT')
    g.socket('Valid', 'NodeSocketBool', 'OUTPUT')
    inp = g.node('NodeGroupInput'); out = g.node('NodeGroupOutput')
    source = inp.outputs['Geometry']; template = inp.outputs['Pattern']; mouths = inp.outputs['Mouths']
    sides = c.V(g, inp.outputs['Pattern Sides']); N = c.V(g, inp.outputs['Pattern Rows'])
    M = c.V(g, inp.outputs['Pattern Radial']); n = c._read(g, inp.outputs['Plan'], 'st_cq_count', 0, 'INT')
    m = c.V(g, inp.outputs['Radial Count'])
    valid = c.V(g, inp.outputs['Input Valid'])*g.math('COMPARE', c._count(g, mouths), sides)
    valid = valid*c._stat(g, mouths, g.math('COMPARE', c.named(g, 'st_cj_half', 'INT'), 0.))
    valid = valid*c._stat(g, inp.outputs['Plan'], g.math('COMPARE', c.named(g, 'st_cq_count', 'INT'), n))
    helper = _Nodes(g.g)
    valid = valid*g.math('COMPARE', bridge._size(helper, source, 'Face Count'), sides*(n*m+n*n*.25))
    chart, row, col = g.separate(c.named(g, 'st_cq_key', 'FLOAT_VECTOR'))
    band = g.math('GREATER_THAN', chart, .5)
    vertex_owner = c.choose(g, band, chart-1., c.choose(g, g.math('COMPARE', chart, 0.), row, 0.))
    # The chart filters source tables by side, so its owner must be a uniform
    # repeat value, not a field evaluated on that different table's domain.
    ri = g.node('GeometryNodeRepeatInput', 'Evaluate each analytic side at fixed pattern parameters')
    ro = g.node('GeometryNodeRepeatOutput'); ri.pair_with_output(ro)
    g.bind(c.choose(g, valid, sides, 0, 'INT'), ri.inputs['Iterations'])
    g.bind(c._store(g, template, '_qp_pin_valid', True, 'BOOLEAN'), ri.inputs['Geometry'])
    owner = c.V(g, ri.outputs['Iteration'])
    field, good = four._chart(g, inp, owner, c.named(g, '_qp_t'), 1.-col/M,
                             allow_taper=True, continuations=continuations, port_paths=True,
                             interpolation=interpolation)
    crown = g.xyz(*four._crown(g, mouths, owner, interpolation=interpolation))
    wanted = c.choose(g, band, field.outputs['Position'], crown, 'VECTOR')
    fixed = c.named(g, 'st_cq_fixed', 'BOOLEAN')
    selected = fixed*g.math('COMPARE', vertex_owner, owner)
    pinned = c.choose(g, selected, wanted, g.position(), 'VECTOR')
    current = g.setpos(ri.outputs['Geometry'], pinned)
    current = c._store(g, current, '_qp_pin_valid', c.choose(g, selected,
        c.choose(g, band, good, True, 'BOOLEAN'), c.named(g, '_qp_pin_valid', 'BOOLEAN'), 'BOOLEAN'), 'BOOLEAN')
    g.bind(current, ro.inputs['Geometry']); constrained = ro.outputs['Geometry']
    valid = valid*c._stat(g, constrained, c.named(g, '_qp_pin_valid', 'BOOLEAN'))
    parameters_valid = valid
    fit = g.node('GeometryNodeGroup', 'Fixed prepared response to analytic boundary constraints')
    fit.node_tree = response.build(expose_input_valid=repair_coarse)
    g.bind(constrained, fit.inputs['Geometry']); g.bind(template, fit.inputs['Pattern'])
    g.bind(inp.outputs['Coefficients'], fit.inputs['Coefficients'])
    fit.inputs['Signed Coefficients'].default_value = True
    # Offline preparation verifies W*reference_pins == reference_free. Direct
    # evaluation is equivalent in real arithmetic and avoids cancellation of
    # large reference displacements under rotation or high arm counts.
    fit.inputs['Reference Deformation'].default_value = False
    valid = c.choose(g, valid, fit.outputs['Valid'], False, 'BOOLEAN')
    if repair_coarse:
        result, accepted, status, fitted = _refined_transfer(g, inp, fit, parameters_valid, valid, n, m, N, M,
                                                          graded_transfer=graded_transfer)
        g.bind(c._select(g,result,accepted),out.inputs['Geometry'])
        g.bind(result,out.inputs['Inspection Geometry']);g.bind(accepted,out.inputs['Valid'])
        g.bind(constrained,out.inputs['Constrained Pattern']);g.bind(fitted,out.inputs['Fitted Pattern'])
        g.bind(status,out.inputs['Status'])
        return g.g
    prolong = g.node('GeometryNodeGroup', 'Retain caller pins and sample matching quad blocks')
    if graded_transfer:
        from . import curved_quad_graded_prolong_nodes as graded
        prolong.node_tree = graded.build()
    else:
        prolong.node_tree = transfer.build()
    for key, value in (('Fine', source), ('Coarse', fit.outputs['Geometry']), ('Mouths', mouths),
            ('Fine Rows', n), ('Fine Radial', m), ('Coarse Rows', N), ('Coarse Radial', M), ('Input Valid', valid)):
        g.bind(value, prolong.inputs[key])
    result = prolong.outputs['Geometry']
    # The existing prolongation is planar. Preserve caller Z explicitly here.
    index = g.node('GeometryNodeInputIndex').outputs[0]
    original = c._sample(g, source, g.position(), index, 'FLOAT_VECTOR')
    x, y, _ = g.separate(g.position()); z = g.separate(original)[2]
    result = g.setpos(result, g.xyz(x, y, z))
    admission = g.node('GeometryNodeGroup', 'Measure pattern cell stretching')
    admission.node_tree = quality.build(); g.bind(result, admission.inputs['Geometry'])
    # Use the independent surface qualification's edge-ratio limit. The
    # optional early-stop certificate also tests stricter corner/area targets;
    # those are not general admission rules for the original street meshes.
    quality_valid = (1.-g.math('GREATER_THAN', admission.outputs['Maximum Edge Ratio'], quality.MAX_EDGE_RATIO))
    valid = c.V(g, prolong.outputs['Valid'])*c.V(g, bridge._mesh_good(helper, result.s))*quality_valid
    status = c._line(g, 1)
    for key, value in (('parameters', parameters_valid), ('fit', fit.outputs['Valid']),
                       ('transfer', prolong.outputs['Valid']), ('quality', quality_valid), ('valid', valid)):
        status = c._store(g, status, '_qp_'+key, value, 'BOOLEAN')
    status = c._store(g, status, '_qp_max_edge_ratio', admission.outputs['Maximum Edge Ratio'])
    g.bind(c._select(g, result, valid), out.inputs['Geometry'])
    g.bind(result, out.inputs['Inspection Geometry']); g.bind(valid, out.inputs['Valid'])
    g.bind(constrained, out.inputs['Constrained Pattern']); g.bind(fit.outputs['Inspection Geometry'], out.inputs['Fitted Pattern'])
    g.bind(status, out.inputs['Status'])
    return g.g


def _refined_transfer(g,inp,fit,parameters_valid,fit_valid,n,m,N,M,*,graded_transfer=False):
    """Try finite alternatives; explicit grading keeps one transfer rule.

    The default preserves its original direct/graded trial order. Explicit
    grading evaluates only graded transfer, before and after coarse correction.
    A correction/fallback switch can still be discontinuous and must be tested.
    """
    from . import curved_quad_graded_prolong_nodes as graded
    from . import curved_quad_pattern_correct_nodes as correction
    helper=_Nodes(g.g);source=inp.outputs['Geometry']
    choose=lambda flag,a,b,kind='BOOLEAN':c.choose(g,flag,a,b,kind)
    index=g.node('GeometryNodeInputIndex').outputs[0]
    original=c._sample(g,source,g.position(),index,'FLOAT_VECTOR')

    def attempt(coarse,allowed,use_grading,label):
        node=g.node('GeometryNodeGroup',label)
        node.node_tree=graded.build() if use_grading else transfer.build()
        for key,value in (('Fine',source),('Coarse',coarse),('Mouths',inp.outputs['Mouths']),
                          ('Fine Rows',n),('Fine Radial',m),('Coarse Rows',N),('Coarse Radial',M),('Input Valid',allowed)):
            g.bind(value,node.inputs[key])
        x,y,_=g.separate(g.position());z=g.separate(original)[2]
        geometry=g.setpos(node.outputs['Geometry'],g.xyz(x,y,z))
        metric=g.node('GeometryNodeGroup','Candidate shape / '+label);metric.node_tree=quality.build()
        g.bind(geometry,metric.inputs['Geometry'])
        shape=1.-g.math('GREATER_THAN',metric.outputs['Maximum Edge Ratio'],quality.MAX_EDGE_RATIO)
        accepted=choose(allowed,c.V(g,node.outputs['Valid'])*c.V(g,bridge._mesh_good(helper,geometry.s))*shape,False)
        return geometry,accepted,node.outputs['Valid'],shape,metric.outputs['Maximum Edge Ratio']

    # An explicit graded transfer uses the same spacing map throughout an
    # edit. Selecting direct versus graded by an edge-ratio cutoff introduces
    # a discontinuity even though their topology and fixed pins are identical.
    # The default retains its original short-circuit ordering unchanged.
    direct=None if graded_transfer else attempt(fit.outputs['Geometry'],fit_valid,False,'Keep accepted direct pattern')
    graded_fit=attempt(fit.outputs['Geometry'],fit_valid if graded_transfer else choose(direct[1],False,fit_valid),True,
                       'Continuous boundary grading' if graded_transfer else 'Try boundary grading only when needed')
    first_ok=graded_fit[1] if graded_transfer else choose(direct[1],True,graded_fit[1])
    data_valid=choose(parameters_valid,fit.outputs['Inputs Valid'],False)
    repair=g.node('GeometryNodeGroup','Correct only an admissible failed coarse placement');repair.node_tree=correction.build()
    g.bind(fit.outputs['Inspection Geometry'],repair.inputs['Geometry'])
    g.bind(choose(first_ok,False,data_valid),repair.inputs['Input Valid'])
    corrected=None if graded_transfer else attempt(repair.outputs['Geometry'],repair.outputs['Valid'],False,'Transfer corrected coarse pattern')
    corrected_graded=attempt(repair.outputs['Geometry'],repair.outputs['Valid'] if graded_transfer else choose(corrected[1],False,repair.outputs['Valid']),True,
                             'Grade corrected coarse pattern only when needed')
    # Choose geometry lazily so successful earlier branches do not require
    # the correction or any later transfer to run.
    result=corrected_graded[0];accepted=corrected_graded[1];ratio=corrected_graded[4]
    path=choose(accepted,3,-1,'INT')
    choices=((1,graded_fit),) if graded_transfer else ((2,corrected),(1,graded_fit),(0,direct))
    for number,candidate in choices:
        result=choose(candidate[1],candidate[0],result,'GEOMETRY')
        ratio=choose(candidate[1],candidate[4],ratio,'FLOAT')
        path=choose(candidate[1],number,path,'INT')
        accepted=choose(candidate[1],True,accepted)
    result=c._store(g,result,'st_cq_pattern_path',path,'INT')
    status=c._line(g,1)
    for key,value in (('parameters',parameters_valid),('fit',fit.outputs['Valid']),('valid',accepted)):
        status=c._store(g,status,'_qp_'+key,value,'BOOLEAN')
    status=c._store(g,status,'_qp_path',path,'INT')
    status=c._store(g,status,'_qp_max_edge_ratio',ratio)
    corrected_used=g.math('GREATER_THAN',path,1.5)
    fitted=choose(corrected_used,repair.outputs['Inspection Geometry'],fit.outputs['Inspection Geometry'],'GEOMETRY')
    return result,accepted,status,fitted
